<script setup>
import { computed, onMounted, ref } from 'vue'
import BigScreenLayout from '../components/layout/BigScreenLayout.vue'
import ChartState from '../components/dashboard/ChartState.vue'
import DashboardPanel from '../components/dashboard/DashboardPanel.vue'
import { getComparison, getComparisonLocations } from '../api/comparison'
import { useEChart } from '../utils/chart'

const locations=ref([]), selectedKeys=ref([]), startDate=ref(''), endDate=ref(''), result=ref(null), loading=ref(false), error=ref(''), requestVersion=ref(0)
const radarElement=ref(null), barElement=ref(null), monthElement=ref(null)
const selectedLocations=computed(()=>selectedKeys.value.map(key=>locations.value.find(item=>item.key===key)).filter(Boolean))
const cities=computed(()=>result.value?.cities||[])
const metrics=city=>city?.weatherMetrics||{}
const format=(value,suffix='')=>value===null||value===undefined?'暂无数据':`${Number(value).toFixed(2)}${suffix}`
const color=index=>['#ff6b7a','#38bdf8','#ffc04d','#34e0a1'][index%4]
const cityLabel=city=>city?`${city.province} · ${city.city}`:'请选择城市'
function addCity(){const next=locations.value.find(item=>!selectedKeys.value.includes(item.key));if(next&&selectedKeys.value.length<4)selectedKeys.value.push(next.key)}
function removeCity(index){if(selectedKeys.value.length>2)selectedKeys.value.splice(index,1)}
function buildParams(){return{cities:selectedKeys.value.join(','),...(startDate.value?{startDate:startDate.value}:{}),...(endDate.value?{endDate:endDate.value}:{})}}
async function query(){if(selectedKeys.value.length<2)return;const token=++requestVersion.value;loading.value=true;error.value='';result.value=null;try{const response=await getComparison(buildParams());if(token!==requestVersion.value)return;result.value=response.data||null;if(!startDate.value)startDate.value=result.value?.weatherPeriod?.startDate||'';if(!endDate.value)endDate.value=result.value?.weatherPeriod?.endDate||''}catch(reason){if(token===requestVersion.value)error.value=reason?.message||'区域对比数据读取失败'}finally{if(token===requestVersion.value)loading.value=false}}
function scale(field,city){const values=cities.value.map(item=>Number(metrics(item)[field])).filter(Number.isFinite);const value=Number(metrics(city)[field]);if(!Number.isFinite(value)||!values.length)return null;const min=Math.min(...values),max=Math.max(...values);return max===min?1:(value-min)/(max-min)}
function scaleAqi(city){const values=cities.value.map(item=>Number(item.aqiSnapshot?.aqi)).filter(Number.isFinite),value=Number(city.aqiSnapshot?.aqi);if(!Number.isFinite(value)||!values.length)return null;const min=Math.min(...values),max=Math.max(...values);return max===min?1:(value-min)/(max-min)}
function radarOption(){const indicators=[{name:'平均温度',max:1},{name:'降水量',max:1},{name:'平均风速',max:1},{name:'AQI快照',max:1}];return{tooltip:{trigger:'item',formatter:params=>{const city=cities.value.find(item=>item.city===params.name);return `${params.name}<br/>平均温度：${format(metrics(city).avgTempEstimate,' ℃')}<br/>区域日均降水累计：${format(metrics(city).totalPrecip,' mm')}<br/>平均风速：${format(metrics(city).avgWind,' m/s')}<br/>AQI固定快照：${city?.aqiSnapshot?.aqi??'暂无数据'}`}},legend:{bottom:0,textStyle:{color:'#b8d9ef'},data:cities.value.map(city=>city.city)},radar:{indicator:indicators,center:['50%','46%'],radius:'60%',axisName:{color:'#cfeeff'},splitArea:{areaStyle:{color:['rgba(18,75,125,.18)','rgba(5,36,75,.18)']}},splitLine:{lineStyle:{color:'rgba(67,171,224,.35)'}},axisLine:{lineStyle:{color:'rgba(67,171,224,.35)'}}},series:[{type:'radar',data:cities.value.map((city,index)=>({name:city.city,value:['avgTempEstimate','totalPrecip','avgWind'].map(field=>scale(field,city)).concat([scaleAqi(city)]),lineStyle:{color:color(index)},itemStyle:{color:color(index)},areaStyle:{color:color(index),opacity:.12}}))}]}}
function barOption(){return{tooltip:{trigger:'axis'},legend:{top:0,textStyle:{color:'#b8d9ef'}},grid:{left:48,right:48,top:38,bottom:30},xAxis:{type:'category',data:cities.value.map(city=>city.city),axisLabel:{color:'#b8d9ef'}},yAxis:[{type:'value',name:'温度 ℃',axisLabel:{color:'#b8d9ef'}},{type:'value',name:'AQI',axisLabel:{color:'#b8d9ef'}}],series:[{name:'估算平均温度',type:'bar',data:cities.value.map(city=>metrics(city).avgTempEstimate),itemStyle:{color:'#38bdf8'}},{name:'AQI固定快照',type:'bar',yAxisIndex:1,data:cities.value.map(city=>city.aqiSnapshot?.aqi),itemStyle:{color:'#ffc04d'}}]}}
function monthOption(){const months=[...new Set(cities.value.flatMap(city=>(city.monthlyPrecip||[]).map(item=>item.month)))].sort();return{tooltip:{trigger:'axis'},legend:{top:0,textStyle:{color:'#b8d9ef'}},grid:{left:48,right:24,top:38,bottom:30},xAxis:{type:'category',data:months,axisLabel:{color:'#b8d9ef'}},yAxis:{type:'value',name:'mm',axisLabel:{color:'#b8d9ef'}},series:cities.value.map((city,index)=>({name:city.city,type:'line',connectNulls:false,data:months.map(month=>city.monthlyPrecip?.find(item=>item.month===month)?.precip??null),lineStyle:{color:color(index)},itemStyle:{color:color(index)}}))}}
useEChart(radarElement,radarOption,[cities],{});useEChart(barElement,barOption,[cities],{});useEChart(monthElement,monthOption,[cities],{})
const conclusion=computed(()=>{if(!cities.value.length)return[];const pick=(field,desc)=>cities.value.filter(city=>metrics(city)[field]!==null).sort((a,b)=>metrics(b)[field]-metrics(a)[field])[0]||null;const temp=pick('avgTempEstimate'),rain=pick('totalPrecip'),wind=pick('avgWind'),aqi=cities.value.filter(city=>Number.isFinite(Number(city.aqiSnapshot?.aqi))).sort((a,b)=>a.aqiSnapshot.aqi-b.aqiSnapshot.aqi)[0];return[{label:'温度最高',city:temp,text:temp?`估算平均温度 ${format(metrics(temp).avgTempEstimate,' ℃')}`:'暂无可比数据'},{label:'降水最多',city:rain,text:rain?`区域日均降水累计 ${format(metrics(rain).totalPrecip,' mm')}`:'暂无可比数据'},{label:'平均风速最大',city:wind,text:wind?`平均风速 ${format(metrics(wind).avgWind,' m/s')}`:'暂无可比数据'},{label:'AQI最低',city:aqi,text:aqi?`固定快照 AQI ${aqi.aqiSnapshot.aqi}`:'暂无AQI快照'}]})
onMounted(async()=>{try{const response=await getComparisonLocations();locations.value=Array.isArray(response.data)?response.data:[];selectedKeys.value=locations.value.filter(item=>['北京::北京','上海::上海'].includes(item.key)).map(item=>item.key);if(selectedKeys.value.length<2)selectedKeys.value=locations.value.slice(0,2).map(item=>item.key);await query()}catch(reason){error.value=reason?.message||'区域选项读取失败'}})
</script>
<template>
<BigScreenLayout page-number="6" title="区域对比分析" description="基于真实天气历史数据与独立 AQI 快照进行区域对比。">
<template #filters><div class="compare-filter"><strong>对比区域</strong><label v-for="(key,index) in selectedKeys" :key="index">城市{{String.fromCharCode(65+index)}}<select v-model="selectedKeys[index]"><option v-for="item in locations" :key="item.key" :value="item.key" :disabled="selectedKeys.includes(item.key)&&selectedKeys[index]!==item.key">{{item.province}} · {{item.city}}</option></select><button v-if="selectedKeys.length>2" type="button" @click="removeCity(index)">移除</button></label><button v-if="selectedKeys.length<4" type="button" @click="addCity">+ 添加城市</button><label>起始日期<input v-model="startDate" type="date"></label><label>结束日期<input v-model="endDate" type="date"></label><button class="query-button" type="button" :disabled="loading" @click="query">查询</button></div></template>
<p v-if="error" class="compare-alert">{{error}}</p><div class="comparison-page"><DashboardPanel title="区域核心指标对比" :subtitle="result?`${result.weatherPeriod.startDate} 至 ${result.weatherPeriod.endDate} · 共同可比观测日 ${result.dataCoverage.commonDays} 天`:'请选择区域并查询'"><ChartState :loading="loading" :error="''" :empty="!result" empty-message="暂无对比数据"><div class="metric-grid"><article v-for="(city,index) in cities" :key="city.key" :style="{'--city-color':color(index)}"><strong>{{cityLabel(city)}}</strong><span>估算平均温度 <b>{{format(metrics(city).avgTempEstimate,' ℃')}}</b></span><span>区域日均降水累计 <b>{{format(metrics(city).totalPrecip,' mm')}}</b></span><span>平均风速 <b>{{format(metrics(city).avgWind,' m/s')}}</b></span><span>AQI固定快照 <b>{{city.aqiSnapshot?.aqi??'暂无数据'}}</b></span></article></div></ChartState></DashboardPanel><div class="compare-grid"><DashboardPanel title="多维指标对比" subtitle="标准化相对量级，越外不代表越好"><ChartState :loading="loading" :error="''" :empty="!result" empty-message="暂无对比数据"><div ref="radarElement" class="chart radar-chart" /></ChartState></DashboardPanel><DashboardPanel title="城市温度与 AQI 对比" subtitle="温度为历史区间估算值，AQI为独立固定快照"><ChartState :loading="loading" :error="''" :empty="!result" empty-message="暂无对比数据"><div ref="barElement" class="chart" /></ChartState></DashboardPanel><DashboardPanel title="月度降水量对比" subtitle="仅展示实际存在数据的月份"><ChartState :loading="loading" :error="''" :empty="!result" empty-message="暂无共同可比数据"><div ref="monthElement" class="chart" /></ChartState></DashboardPanel></div><DashboardPanel title="城市指标对比" :subtitle="result?`有效天气观测日：${result.dataCoverage.cities.map(item=>item.validDays).join(' / ')} 天`:''"><ChartState :loading="loading" :error="''" :empty="!result" empty-message="暂无对比数据"><div class="compare-table-wrap"><table><thead><tr><th>城市</th><th>平均温度</th><th>平均最高温</th><th>平均最低温</th><th>区域日均降水累计</th><th>平均风速</th><th>最大风速</th><th>AQI快照</th><th>有效天数</th></tr></thead><tbody><tr v-for="city in cities" :key="city.key"><td>{{cityLabel(city)}}</td><td>{{format(metrics(city).avgTempEstimate,' ℃')}}</td><td>{{format(metrics(city).avgMaxTemp,' ℃')}}</td><td>{{format(metrics(city).avgMinTemp,' ℃')}}</td><td>{{format(metrics(city).totalPrecip,' mm')}}</td><td>{{format(metrics(city).avgWind,' m/s')}}</td><td>{{format(metrics(city).maxWind,' m/s')}}</td><td>{{city.aqiSnapshot?.aqi??'暂无数据'}}</td><td>{{metrics(city).validDays}}</td></tr></tbody></table></div></ChartState></DashboardPanel><DashboardPanel title="区域对比分析结论" subtitle="基于共同可比天气观测日期与独立 AQI 快照"><div class="conclusions"><p v-for="item in conclusion" :key="item.label"><b>{{item.label}}</b><span>{{item.city?cityLabel(item.city):''}} {{item.text}}</span></p></div></DashboardPanel></div>
</BigScreenLayout></template>
<style scoped>
.compare-filter{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:7px 12px;color:var(--text-muted);font-size:11px;background:linear-gradient(90deg,rgb(6 42 81/.92),rgb(4 28 61/.84));border:1px solid rgb(35 143 211/.58);border-radius:6px}.compare-filter strong{color:var(--accent-cyan);font-size:13px}.compare-filter label{display:inline-flex;align-items:center;gap:5px}.compare-filter select,.compare-filter input{height:31px;min-width:125px;padding:4px 7px;color:var(--text-primary);background:#0b315f;border:1px solid rgb(45 151 216/.68);border-radius:4px}.compare-filter button{height:30px;padding:0 8px;color:#cdeeff;background:#0b477a;border:1px solid #287fb6;border-radius:4px;cursor:pointer}.compare-filter .query-button{padding:0 16px;color:#fff;background:#0877bd;border-color:#39cdfb}.compare-filter button:disabled{opacity:.55}.compare-alert{padding:8px 12px;color:#ff9fae;background:rgb(100 24 48/.32);border:1px solid rgb(255 125 134/.4);border-radius:6px}.comparison-page{display:flex;min-height:0;flex:1;flex-direction:column;gap:12px}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric-grid article{display:flex;min-height:110px;flex-direction:column;gap:7px;padding:13px;border-left:3px solid var(--city-color);background:linear-gradient(145deg,rgb(7 49 94/.8),rgb(3 26 58/.78));border:1px solid rgb(36 145 211/.52);border-radius:7px}.metric-grid strong{color:var(--city-color);font-size:14px}.metric-grid span{color:var(--text-secondary);font-size:11px}.metric-grid b{color:var(--text-primary);font-size:16px}.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.compare-grid .dashboard-panel:last-child{grid-column:1 / -1}.chart{width:100%;height:320px}.radar-chart{height:350px}.compare-table-wrap{overflow:auto}.compare-table-wrap table{width:100%;border-collapse:collapse;color:var(--text-secondary);font-size:11px}.compare-table-wrap th,.compare-table-wrap td{padding:9px 8px;text-align:center;border:1px solid rgb(45 126 177/.4)}.compare-table-wrap th{color:#cdeeff;background:rgb(8 58 106/.8)}.compare-table-wrap td:first-child{text-align:left;color:var(--text-primary)}.conclusions{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.conclusions p{display:flex;gap:14px;margin:0;padding:10px;color:var(--text-secondary);background:rgb(7 49 94/.55);border:1px solid rgb(36 145 211/.42);border-radius:6px}.conclusions b{min-width:90px;color:var(--accent-cyan)}@media(max-width:1100px){.metric-grid{grid-template-columns:repeat(2,1fr)}.compare-grid{grid-template-columns:1fr}}@media(max-width:700px){.metric-grid,.conclusions{grid-template-columns:1fr}.compare-filter{align-items:flex-start;flex-direction:column}}
</style>
